(5682988, 825773, 40370, '<td valign="top">Extreme flower of flame.</td>', 'Extreme flower of flame.', '2009-10-10 21:41:38.000000', NULL, 1),
(5682999, 825652, 40370, '<td valign="top">Focus is strong on the lighter, I''d like to see a different composition though, less hand and more dark negative space above the flame.</td>', 'Focus is strong on the lighter, I''d like to see a different composition though, less hand and more dark negative space above the flame.', '2009-10-10 21:46:55.000000', NULL, 1),
(5683003, 825771, 40370, '<td valign="top">Complete enthusiasm for the cake and candles, great clarity ... why the pumpkin and flower backdrop (maybe the title explains)?</td>', 'Complete enthusiasm for the cake and candles, great clarity ... why the pumpkin and flower backdrop (maybe the title explains)?', '2009-10-10 21:55:35.000000', NULL, 1),
(5683004, 824846, 40370, '<td valign="top">My son would love a poster print of this image. Very October/Terminator connection. Fun.</td>', 'My son would love a poster print of this image. Very October/Terminator connection. Fun.', '2009-10-10 21:58:35.000000', NULL, 1),
(5683005, 825262, 40370, '<td valign="top">Sorry, almost finished voting, and a sunset, even though a beautiful photo like this, just doesn''t compete with the other fire images. 4</td>', 'Sorry, almost finished voting, and a sunset, even though a beautiful photo like this, just doesn''t compete with the other fire images. 4', '2009-10-10 22:02:40.000000', NULL, 1),
(5683007, 825446, 54645, '<td valign="top">Lovely scene. Story is excellent. Great job.</td>', 'Lovely scene. Story is excellent. Great job.', '2009-10-10 22:08:23.000000', NULL, 1),
(5683011, 825452, 54645, '<td valign="top">Beautiful abstract, bottom third is peaceful but then transitions in to intense heat and movement. Your get a 10 from me. <br/> <br/>Love this photograph. My only 10 for the challenge.</td>', 'Beautiful abstract, bottom third is peaceful but then transitions in to intense heat and movement. Your get a 10 from me.  Love this photograph. My only 10 for the challenge.', '2009-10-10 22:09:15.000000', NULL, 1),
(5683012, 825384, 40370, '<td valign="top">I love the unique subject in this image and can see myself taking multiple pics of the same thing, however to be strong is this challenge, I think I would have cropped the top and bottom quarter to enhance the detail of the subject.</td>', 'I love the unique subject in this image and can see myself taking multiple pics of the same thing, however to be strong is this challenge, I think I would have cropped the top and bottom quarter to enhance the detail of the subject.', '2009-10-10 22:11:08.000000', NULL, 1),
(5683013, 825659, 54645, '<td valign="top">I tried to get up there to photograph the fire. This is a fantastic scene that captures the intense mood and heat. Definitely abstract, and I doubt many voters would see this as a fire without the title.Well done. 9 from me.</td>', 'I tried to get up there to photograph the fire. This is a fantastic scene that captures the intense mood and heat. Definitely abstract, and I doubt many voters would see this as a fire without the title.Well done. 9 from me.', '2009-10-10 22:11:18.000000', NULL, 1),
(5683014, 825426, 40370, '<td valign="top">I am always fascinated by the embers ... nice image.</td>', 'I am always fascinated by the embers ... nice image.', '2009-10-10 22:12:54.000000', NULL, 1),
(5683015, 825655, 40370, '<td valign="top">Pure melting - burning heat ... the title says it all, so does the image.</td>', 'Pure melting - burning heat ... the title says it all, so does the image.', '2009-10-10 22:14:26.000000', NULL, 1),
(5683016, 825698, 40370, '<td valign="top">i like the cross section composition however the photo overall is a little dark</td>', 'i like the cross section composition however the photo overall is a little dark', '2009-10-10 22:15:12.000000', NULL, 1),
(5683017, 825707, 40370, '<td valign="top">Bring on the dancers ... 1, 2, 3 ... 4, it''s still my fantasy. Nice.</td>', 'Bring on the dancers ... 1, 2, 3 ... 4, it''s still my fantasy. Nice.', '2009-10-10 22:16:41.000000', NULL, 1),
