(5683846, 825764, 83313, '<td valign="top">Very cute, though for this site it comes off kinda snapshotty.</td>', 'Very cute, though for this site it comes off kinda snapshotty.', '2009-10-11 22:48:02.000000', NULL, 1),
(5683847, 825552, 83313, '<td valign="top">A lot of high ISO grain, and the whole image seems soft and a visually flat. Perhaps some adjustments could help it a bit. Not sure though. I do feel a snack attack coming on, however, so this shot was effective in that regard.</td>', 'A lot of high ISO grain, and the whole image seems soft and a visually flat. Perhaps some adjustments could help it a bit. Not sure though. I do feel a snack attack coming on, however, so this shot was effective in that regard.', '2009-10-11 22:48:09.000000', NULL, 1),
(5683848, 825262, 83313, '<td valign="top">Sweet sunset, but a stretch that to me does not really suit the spirit of the challenge. And yes, the sun IS a big ball of fire. Well, technically plasma and other nasty stuff.</td>', 'Sweet sunset, but a stretch that to me does not really suit the spirit of the challenge. And yes, the sun IS a big ball of fire. Well, technically plasma and other nasty stuff.', '2009-10-11 22:48:21.000000', NULL, 1),
(5683849, 824684, 83313, '<td valign="top">Sorry, as nice as this may be, I really cannot fit sunset colors to the spirit of the challenge.</td>', 'Sorry, as nice as this may be, I really cannot fit sunset colors to the spirit of the challenge.', '2009-10-11 22:48:27.000000', NULL, 1),
(5683850, 825631, 83313, '<td valign="top">Cute photo, but where is the fire? Certainly not the tiles on the shower floor?</td>', 'Cute photo, but where is the fire? Certainly not the tiles on the shower floor?', '2009-10-11 22:48:30.000000', NULL, 1),
(5683851, 825395, 83313, '<td valign="top">Great shot, and I would love to give this a high vote, but I don''t feel a sunset fits the spirit of this challenge, no matter how awesome it is. Sorry.</td>', 'Great shot, and I would love to give this a high vote, but I don''t feel a sunset fits the spirit of this challenge, no matter how awesome it is. Sorry.', '2009-10-11 22:48:36.000000', NULL, 1),
(5683852, 825659, 83313, '<td valign="top">Awesome photo, but I have had to make the decision that a "fiery sunset" does not fit the spirit of this challenge. Though it is possible this place was ravaged by fire, this does not carry across to me in the image. Again, a wonderful shot that I hate giving a low vote to, but I must. To do otherwise is unfair to the entries that did do something related to actual fire.</td>', 'Awesome photo, but I have had to make the decision that a "fiery sunset" does not fit the spirit of this challenge. Though it is possible this place was ravaged by fire, this does not carry across to me in the image. Again, a wonderful shot that I hate giving a low vote to, but I must. To do otherwise is unfair to the entries that did do something related to actual fire.', '2009-10-11 22:48:38.000000', NULL, 1),
(5683920, 825771, 70000, '<td valign="top">Nicely exposed, I think the photo would be far more effective without the pumpkin and plants in the background. It would have more impact on the brownie having so many candles in it.</td>', 'Nicely exposed, I think the photo would be far more effective without the pumpkin and plants in the background. It would have more impact on the brownie having so many candles in it.', '2009-10-12 00:56:11.000000', NULL, 1),
