(5686772, 825761, 101678, '<td valign="top">That is TREMENDOUS Andres!  Congrats on the blue!  So well deserved. Great to see this in both places.</td>', 'That is TREMENDOUS Andres!  Congrats on the blue!  So well deserved. Great to see this in both places.', '2009-10-14 10:23:10.000000', NULL, 0),
(5686775, 824827, 101678, '<td valign="top">What a fantastic shot.  Huge congrats on the Red, and if I find out who gave this a 1, I''m going to take them out back and do things to them they haven''t dreamed possible.</td>', 'What a fantastic shot.  Huge congrats on the Red, and if I find out who gave this a 1, I''m going to take them out back and do things to them they haven''t dreamed possible.', '2009-10-14 10:24:18.000000', NULL, 0),
